public class Main {
    public static void main(String[] args) {
        int i = 1;
        int sum = 0;

        while (i <= 10) {
            // 짝수는 2로 나누었을 때 나머지가 0이어야 함
            if (i % 2 == 0) {
                sum += i;
            }
            // 반복문이 진행될 수 있도록 i를 1씩 증가
            i++;
        }

        System.out.println("1부터 10까지 짝수의 합: " + sum);
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.println("=== 구구단 프로그램 ===");
        System.out.println("1. 특정 단 출력");
        System.out.println("2. 전체 구구단 (2~9단) 출력");
        System.out.print("메뉴를 선택하세요: ");
        int menu = scanner.nextInt();
        System.out.println(menu);

        switch (menu) {
            case 1:
                System.out.print("출력할 단(2~9)을 입력하세요: ");
                int dan = scanner.nextInt();
                System.out.println(dan);
                if (dan >= 2 && dan <= 9) {
                    System.out.println("--- " + dan + "단 ---");
                    for (int i = 1; i <= 9; i++) {
                        System.out.println(dan + " * " + i + " = " + (dan * i));
                    }
                } else {
                    System.out.println("2단부터 9단까지만 입력 가능합니다.");
                }
                break;

            case 2:
                System.out.println("--- 전체 구구단 ---");
                for (int d = 2; d <= 9; d++) {
                    System.out.println("[" + d + "단]");
                    for (int i = 1; i <= 9; i++) {
                        System.out.println(d + " * " + i + " = " + (d * i));
                    }
                    System.out.println(); // 단별 줄바꿈
                }
                break;

            default:
                System.out.println("잘못된 메뉴 선택입니다.");
                break;
        }

        scanner.close();
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        int score = scanner.nextInt();

        // 범위 검사
        if (score < 0 || score > 100) {
            System.out.println("잘못된 점수입니다.");
        } else {
            char grade;
            if (score >= 90) {
                grade = 'A';
            } else if (score >= 80) {
                grade = 'B';
            } else if (score >= 70) {
                grade = 'C';
            } else if (score >= 60) {
                grade = 'D';
            } else {
                grade = 'F';
            }
            System.out.println("입력한 점수: " + score + "점");
            System.out.println("성적 등급: " + grade);
        }

        scanner.close();
    }
}

public class Main {
    public static void main(String[] args) {
        String[] names = {"김철수", "이영희", "홍길동", "박민수"};
        String target = "홍길동";
        int targetIndex = -1;

        // 1. 인덱스 조건 수정: i < names.length (0부터 length - 1까지)
        for (int i = 0; i < names.length; i++) {
            // 2. 문자열 내용 비교 시 .equals() 메서드 사용
            if (names[i].equals(target)) {
                targetIndex = i;
                break;
            }
        }

        if (targetIndex != -1) {
            System.out.println(target + "은(는) " + targetIndex + "번 인덱스에 있습니다.");
        } else {
            System.out.println(target + "을(를) 찾을 수 없습니다.");
        }
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.print("단어나 문장을 입력하세요: ");
        String original = scanner.nextLine();
        System.out.println(original);

        // StringBuilder 객체 생성
        StringBuilder sb = new StringBuilder(original);

        // 문자열 뒤집기
        String reversed = sb.reverse().toString();

        System.out.println("뒤집힌 문자열: " + reversed);

        // 회문 검사 (대소문자 구분 없음)
        if (original.equalsIgnoreCase(reversed)) {
            System.out.println("결과: '" + original + "'은(는) 회문(Palindrome)입니다.");
        } else {
            System.out.println("결과: '" + original + "'은(는) 회문이 아닙니다.");
        }

        scanner.close();
    }
}

