class BankAccount {
    String accountNumber;
    String owner;
    int balance;

    // 생성자
    public BankAccount(String accountNumber, String owner) {
        this.accountNumber = accountNumber;
        this.owner = owner;
        this.balance = 0; // 초기 잔액 0원
    }

    // 입금 메서드
    public void deposit(int amount) {
        this.balance += amount;
        System.out.println(amount + "원이 입금되었습니다.");
    }

    // 출금 메서드
    public void withdraw(int amount) {
        if (this.balance >= amount) {
            this.balance -= amount;
            System.out.println(amount + "원이 출금되었습니다.");
        } else {
            System.out.println("출금 실패: 잔액이 부족합니다. (현재 잔액: " + this.balance + "원)");
        }
    }

    // 잔액 조회 메서드
    public void printBalance() {
        System.out.println("[" + owner + "님의 계좌 " + accountNumber + "] 현재 잔액: " + balance + "원");
    }
}

public class Main {
    public static void main(String[] args) {
        BankAccount myAccount = new BankAccount("110-123-4567", "홍길동");

        myAccount.printBalance();
        myAccount.deposit(10000);
        myAccount.withdraw(3000);
        myAccount.withdraw(8000); // 잔액 부족 케이스
        myAccount.printBalance();
    }
}

class Student {
    String name;
    int score;

    public Student(String name, int score) {
        this.name = name;
        this.score = score;
    }

    public void printStudent() {
        System.out.println("이름: " + name + " | 점수: " + score + "점");
    }
}

public class Main {
    public static void main(String[] args) {
        // 객체 배열 선언 및 생성
        Student[] students = new Student[3];

        // 객체 배열 요소 초기화
        students[0] = new Student("김철수", 85);
        students[1] = new Student("이영희", 92);
        students[2] = new Student("박민수", 78);

        int totalScore = 0;

        System.out.println("=== 학생 명단 및 점수 ===");
        for (int i = 0; i < students.length; i++) {
            students[i].printStudent();
            totalScore += students[i].score;
        }

        double average = (double) totalScore / students.length;

        System.out.println("=========================");
        System.out.println("전체 학생 수: " + students.length + "명");
        System.out.printf("학급 평균 점수: %.2f점\n", average);
    }
}

class Employee {
    // 1. 필드를 private으로 변경하여 은닉화
    private String name;
    private int salary;

    public Employee(String name, int salary) {
        this.name = name;
        setSalary(salary); // 생성자에서도 유효성 검사를 적용할 수 있도록 Setter 활용
    }

    // Getter / Setter 구현
    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public int getSalary() {
        return salary;
    }

    // 2. Setter에서 데이터 유효성 검증
    public void setSalary(int salary) {
        if (salary < 0) {
            System.out.println("오류: 급여는 음수가 될 수 없습니다.");
        } else {
            this.salary = salary;
        }
    }
}

public class Main {
    public static void main(String[] args) {
        Employee emp = new Employee("홍길동", 3000000);

        // 3. 필드 직접 접근 대신 Setter 사용
        emp.setSalary(-500000); // 잘못된 값 전달 시도

        // 4. Getter를 사용하여 출력
        System.out.println("이름: " + emp.getName());
        System.out.println("급여: " + emp.getSalary() + "원");
    }
}

