abstract class Monster {
    protected String name;
    protected int hp;

    public Monster(String name, int hp) {
        this.name = name;
        this.hp = hp;
    }

    // 일반 메서드 (모든 몬스터 공통)
    public void takeDamage(int damage) {
        this.hp -= damage;
        if (this.hp < 0) this.hp = 0;
        System.out.println(name + "이(가) " + damage + "의 피해를 입었습니다. (남은 HP: " + hp + ")");
    }

    // 추상 메서드 (자식 클래스에서 반드시 구현)
    public abstract void attack();
}

class Slime extends Monster {
    public Slime(String name, int hp) {
        super(name, hp);
    }

    @Override
    public void attack() {
        System.out.println(name + "이(가) 몸통 박치기를 시도합니다! (데미지: 10)");
    }
}

class Dragon extends Monster {
    public Dragon(String name, int hp) {
        super(name, hp);
    }

    @Override
    public void attack() {
        System.out.println(name + "이(가) 화염 브레스를 뿜습니다! (데미지: 50)");
    }
}

public class Main {
    public static void main(String[] args) {
        Monster[] monsters = new Monster[2];
        monsters[0] = new Slime("초록 슬라임", 30);
        monsters[1] = new Dragon("레드 드래곤", 200);

        System.out.println("=== 몬스터 전투 개시 ===");
        for (Monster m : monsters) {
            m.attack();
            m.takeDamage(15);
            System.out.println();
        }
    }
}

