interface Playable {
    void play(String fileName);

    default void stop() {
        System.out.println("[미디어] 재생을 정지합니다.");
    }
}

interface Transferable {
    void sendData(String destination);
}

class SmartPhone implements Playable, Transferable {
    private String modelName;

    public SmartPhone(String modelName) {
        this.modelName = modelName;
    }

    @Override
    public void play(String fileName) {
        System.out.println("[" + modelName + "] '" + fileName + "' 음원을 재생합니다.");
    }

    @Override
    public void sendData(String destination) {
        System.out.println("[" + modelName + "] " + destination + "(으)로 데이터를 전송합니다.");
    }
}

public class Main {
    public static void main(String[] args) {
        SmartPhone phone = new SmartPhone("Galaxy S24");

        // Playable 기능 호출
        phone.play("Off Official - Hype Boy.mp3");
        phone.stop();

        System.out.println();

        // Transferable 기능 호출
        phone.sendData("노트북");
    }
}

