import java.util.HashMap;
import java.util.Map;

// 1. 인터페이스
interface DiscountPolicy {
    int getDiscountPrice(int originalPrice);
}

// 2. 구현 클래스 1
class VipDiscount implements DiscountPolicy {
    @Override
    public int getDiscountPrice(int originalPrice) {
        return (int) (originalPrice * 0.8); // 20% 할인
    }
}

// 3. 구현 클래스 2
class RegularDiscount implements DiscountPolicy {
    @Override
    public int getDiscountPrice(int originalPrice) {
        return (int) (originalPrice * 0.95); // 5% 할인
    }
}

public class Main {
    public static void main(String[] args) {
        // 다형성을 적용한 Map 컬렉션 (Value에 인터페이스 타입 지정)
        Map<String, DiscountPolicy> memberPolicies = new HashMap<>();

        memberPolicies.put("김철수", new VipDiscount());
        memberPolicies.put("이영희", new RegularDiscount());

        int itemPrice = 10000;

        System.out.println("=== 회원별 10,000원 상품 결제 금액 ===");
        for (String name : memberPolicies.keySet()) {
            DiscountPolicy policy = memberPolicies.get(name);
            int finalPrice = policy.getDiscountPrice(itemPrice);
            System.out.println(name + "님의 최종 결제 금액: " + finalPrice + "원");
        }
    }
}

