#include <iostream>
using namespace std;
enum class MENU{PLUS = 1, MUL, MOD, MINUS};

class Add {
    int a, b, cnt;
public:
    Add() { cnt = 0; }
    void setValue(int x, int y) { a = x; b = y; }
    int calculate() { ++cnt; return a + b; }
    int getCnt() { return cnt; }
};

class Mul {
    int a, b, cnt;
public:
    Mul() { cnt = 0; }
    void setValue(int x, int y) { a = x; b = y; }
    int calculate() { ++cnt; return a * b; }
    int getCnt() { return cnt; }
};

class Mod {
    int a, b, cnt;
public:
    Mod() { cnt = 0; }
    void setValue(int x, int y) { a = x; b = y; }
    int calculate() { ++cnt; return a % b; }
    int getCnt() { return cnt; }
};

class Minus {
    int a, b, cnt;
public:
    Minus() { cnt = 0; }
    void setValue(int x, int y) { a = x; b = y; }
    int calculate() { ++cnt; return a - b; }
    int getCnt() { return cnt; }
};

