                for (int d = 2; d <= 9; d++) {
                    System.out.println("[" + d + "단]");
                    for (int i = 1; i <= 9; i++) {
                        System.out.println(d + " * " + i + " = " + (d * i));
                    }
                    System.out.println(); // 단별 줄바꿈
                }
                break;

            default:
