    public void withdraw(int amount) throws BalanceInsufficientException {
        if (this.balance < amount) {
            throw new BalanceInsufficientException("잔액 부족 (현재: " + balance + "원, 요청: " + amount + "원)");
        }
        this.balance -= amount;
        System.out.println(amount + "원 출금 완료 (남은 잔액: " + balance + "원)");
    }
}

