#include <iostream>
#include <cstring>
using namespace std;

class Book {
    char *title;  // 제목 문자열
    int price;   // 가격
public:
    Book(const char* t, int p) : price(p) {
        if (t) {
            title = new char[strlen(t) + 1];
            strcpy(title, t);
        } else {
            title = nullptr;
        }
    }

    ~Book() {
        delete[] title;
    }

    void set(const char* t, int p) {
        if (title) delete[] title;
        if (t) {
            title = new char[strlen(t) + 1];
            strcpy(title, t);
        } else {
            title = nullptr;
        }
        price = p;
    }

    // 디폴트 복사 생성자 (컴파일러가 생성하는 것)
    /*
    Book(const Book &other) : price(other.price) {
        title = other.title;  // 얕은 복사 (문제 발생 원인)
    }
    */

    // 복사 생성자 (깊은 복사)
    Book(const Book &other) : price(other.price) {
        if (other.title) {
            title = new char[strlen(other.title) + 1];
            strcpy(title, other.title);
        } else {
            title = nullptr;
        }
    }

    // 이동 생성자
    Book(Book&& other) noexcept : title(other.title), price(other.price) {
        other.title = nullptr;
        other.price = 0;
    }

    void show() {
        cout << title << ' ' << price << "원" << endl;
    }
};

